public class CanteenPaymentDispatch {double pay(double a){System.out.println("Paid (cash): Rs "+a);return a;}static class CardPayment extends CanteenPaymentDispatch{double payWithProcessingFee(double a){double t=a*1.02;System.out.println("Charged (card, incl. fee): Rs "+t);return t;}}static double processTransaction(CanteenPaymentDispatch p,double a){return p instanceof CardPayment?((CardPayment)p).payWithProcessingFee(a):p.pay(a);}public static void main(String[]x){CanteenPaymentDispatch[]p={new CardPayment(),new CanteenPaymentDispatch(),new CardPayment(),new CanteenPaymentDispatch(),new CardPayment()};double[]a={100,50,200,75,120};double total=0;for(int i=0;i<p.length;i++)total+=processTransaction(p[i],a[i]);System.out.println("Total Collected: Rs "+total);}}
